az3_urls = []
az3_links = []
for d in AZ3_COUNTIES:
    sources = [
        ('Arizona DEQ — Onsite Wastewater Treatment Facilities', AZ3_STATE),
        ('Arizona DEQ — county delegation agreements', AZ3_DELEGATION),
        ('Arizona DEQ — current Type 4 onsite general permits', AZ3_TYPE4),
        ('Arizona DEQ — inspection and notice of transfer', AZ3_TRANSFER),
    ] + d['sources']
    sections = [
        ('Arizona statewide permit framework', 'ADEQ states that it has authority for onsite wastewater treatment facilities and has delegated permitting to all 15 counties. State rules continue to apply, while a delegated county may impose separate or stricter local requirements. Submit through the county where the property is located unless the county or ADEQ identifies a system that remains under direct state jurisdiction.'),
        ('Construction Authorization and Discharge Authorization are separate', 'The Arizona Type 4 process requires a Notice of Intent to Construct and approval before construction. Once the permitted construction, inspection, and testing are complete, the applicant follows the Request or Notice of Intent to Discharge process and obtains Discharge Authorization. Do not treat plan acceptance, a soil report, or an incomplete inspection as final approval.'),
        ('Arizona property transfers have statewide timing requirements', 'ADEQ states that the seller must retain a certified inspector and complete the transfer inspection within six months before the transfer date. The seller provides the inspection report and available system documents to the buyer. The buyer must submit the applicable Notice of Transfer and fee within 15 calendar days after transfer. For these counties, ADEQ currently directs the Notice of Transfer through its statewide online portal unless county instructions say otherwise.'),
    ] + d['sections']
    url = write_county_page(
        'Arizona',
        'arizona',
        d['county'],
        d['authority'],
        d['contact'],
        sections,
        sources,
        verified='September 1, 2026',
    )
    az3_urls.append(url)
    az3_links.append((d['county'], d['authority']))

all_az_links = []
for item in AZ_COUNTIES:
    all_az_links.append((item['county'], item['authority']))
for item in AZ2_COUNTIES:
    all_az_links.append((item['county'], item['authority']))
all_az_links.extend(az3_links)

write_hub(
    'Arizona',
    'arizona',
    sorted(all_az_links),
    'All 15 Arizona counties now have source-checked SepticScope guides. ADEQ retains statewide authority and delegates onsite-wastewater permitting functions to each county, while the local scope, application process, fees, inspections, records access, and professional requirements vary.',
    'Each county guide identifies the responsible local program and distinguishes ordinary county-delegated permitting from systems that may require direct ADEQ review. Confirm jurisdiction for Tribal lands, incorporated areas, alternative technology, large flows, and unusual projects before filing.',
)

sitemap = OUTPUT / 'sitemap.xml'
if sitemap.exists():
    sm = sitemap.read_text(encoding='utf-8')
else:
    sm = '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"></urlset>'
entries = ''.join(
    f'<url><loc>{url}</loc><lastmod>2026-09-01</lastmod></url>'
    for url in az3_urls
    if url not in sm
)
if entries:
    sm = sm.replace('</urlset>', entries + '</urlset>')
    sitemap.write_text(sm, encoding='utf-8')

# Fail the production build immediately if any of the new guides were overwritten
# by the nationwide fallback layer or omitted from the completed state hub.
for county, _authority in az3_links:
    slug = slugify(county)
    page = OUTPUT / 'counties' / 'arizona' / slug / 'index.html'
    text = page.read_text(encoding='utf-8')
    if 'Official sources' not in text or 'Local guide in progress' in text or 'noindex' in text.lower():
        raise RuntimeError(f'Arizona completion page failed validation: {page}')

hub = (OUTPUT / 'counties' / 'arizona' / 'index.html').read_text(encoding='utf-8')
if 'All 15 Arizona counties now have source-checked SepticScope guides' not in hub:
    raise RuntimeError('Arizona completion hub did not retain the completed-state notice')
for county, _authority in all_az_links:
    if f'/counties/arizona/{slugify(county)}/' not in hub:
        raise RuntimeError(f'Arizona hub is missing {county} County')

print('Arizona county completion: +8 verified county guides; all 15 counties covered')
